const {chromium}=require(process.env.ADC_PLAYWRIGHT_MODULE||'playwright');
const fs=require('node:fs'),path=require('node:path');
(async()=>{const browser=await chromium.launch({headless:true});try{
 const [base,area,runtime]=process.argv.slice(2),context=await browser.newContext({viewport:{width:1280,height:960}});await context.addCookies([{name:'adc_session',value:'contribution-fixture',url:base}]);const page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto(base+'/contributions?org=org');await page.getByText('Public intake is off',{exact:true}).waitFor();await page.getByText('Prepare a public contribution queue',{exact:true}).click();
 await page.getByLabel('Responsible area').selectOption(area);await page.getByLabel('Public scope',{exact:true}).fill('Public calculator development only');await page.getByLabel('Public source URL').fill('https://example.test/public-calculator');await page.getByLabel('Internal reviewer').selectOption('qa');await page.getByLabel('Your review subscription').selectOption('account');await page.getByLabel('Validation runtime').selectOption(runtime);await page.getByLabel('Authorize this owner',{exact:false}).check();
 const dir=path.resolve(__dirname,'../../../../work');fs.mkdirSync(dir,{recursive:true});await page.screenshot({path:path.join(dir,'ui-contribution-desktop.png'),fullPage:true});await page.setViewportSize({width:390,height:844});if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('Phone overflow');await page.screenshot({path:path.join(dir,'ui-contribution-mobile.png'),fullPage:true});
 await page.getByRole('button',{name:'Approve queue policy',exact:true}).click();await page.getByRole('heading',{name:'Public calculator development only',exact:true}).waitFor();
 const rejected=await page.request.post(base+'/contribution-action?org=org',{form:{action:'create'}});if(rejected.status()!==403)throw Error('Missing CSRF accepted');if(errors.length)throw Error(errors.join('\n'));console.log('PASS: public-off state, explicit disclosure/funding policy, mobile layout and CSRF');
}finally{await browser.close()}})().catch(e=>{console.error(e);process.exitCode=1});
